import base64

from ..tables import p


title = "Operations with bytes literals"

table_data = {
    p: r"""
          |  by1
        --+------
        1 | a123/AAAAAAAAAAAAAAAAA==
        2 | AAAAAAAAAAAAAAAAAAAAAA==
        3 |
        """,
}


# Shorthand for the autogenerated docs
def _decode(base64_representation):
    return base64.b64decode(base64_representation, validate=True)


def test_equals_fixed_literal_value(spec_test):
    spec_test(
        table_data,
        p.by1 == _decode("a123/AAAAAAAAAAAAAAAAA=="),
        {1: True, 2: False, 3: None},
    )


def test_not_equals_fixed_literal_value(spec_test):
    spec_test(
        table_data,
        p.by1 != _decode("a123/AAAAAAAAAAAAAAAAA=="),
        {1: False, 2: True, 3: None},
    )


def test_is_in_with_fixed_literal_values(spec_test):
    spec_test(
        table_data,
        p.by1.is_in(
            [_decode("a123/AAAAAAAAAAAAAAAAA=="), _decode("AAAAAAAAAAAAAAAAAAAAAA==")]
        ),
        {
            1: True,
            2: True,
            3: None,
        },
    )


def test_map_values_with_fixed_literal_values(spec_test):
    spec_test(
        table_data,
        p.by1.map_values(
            {
                _decode("a123/AAAAAAAAAAAAAAAAA=="): "a",
                _decode("AAAAAAAAAAAAAAAAAAAAAA=="): "b",
            },
            default="c",
        ),
        {1: "a", 2: "b", 3: "c"},
    )
